{% set artworkcreator = resource.artworkcreator|default('') %}
{% set creator = resource.creator|default('') %}
{# The creator field holds either photographers or digitization firms; the digitization_partners
   list in connector.yml decides which is which (case-insensitive, agreed with meemoo). #}
{% set photographers = [] %}
{% set digitization_partner_names = [] %}
{% for creator_value in creator|split(',') %}
{% set creator_name = creator_value|trim %}
{% if creator_name is not empty %}
{% if creator_name|lower in digitization_partners %}
{% set digitization_partner_names = digitization_partner_names|merge([creator_name]) %}
{% else %}
{% set photographers = photographers|merge([creator_name]) %}
{% endif %}
{% endif %}
{% endfor %}
{% if artworkcreator|trim is not empty or photographers is not empty %}

{% if artworkcreator|trim is not empty %}
{% for artworkcreator_value in artworkcreator|split(',') %}
{% set maker = artworkcreator_value|replace({' (Vervaardiger)': '', '(Vervaardiger)': ''})|trim %}
{% if maker|slice(-2) == '()' %}
{% set maker = maker|slice(0, -2)|trim %}
{% endif %}
{% if maker is not empty %}
    {{ maker|e }}
{% endif %}
{% endfor %}
{% endif %}
{% for photographer in photographers %}
    {{ photographer|e }}
{% endfor %}

{% endif %}
{% set contributor = resource.contributor|default('') %}
{% if contributor|trim is not empty or digitization_partner_names is not empty %}

{% if contributor|trim is not empty %}
{% for contributor_value in contributor|split(',') %}
{% set contributor_name = contributor_value|trim %}
{% if contributor_name is not empty %}
    {{ contributor_name|e }}
{% endif %}
{% endfor %}
{% endif %}
{% for digitization_partner in digitization_partner_names %}
    {{ digitization_partner|e }}
{% endfor %}

{% endif %}
{% set subjects = [] %}
{% set subject_keys = [] %}
{% set keywords = resource.keywords|default('') %}
{% if keywords|trim is not empty %}
{% for keyword_value in keywords|split(',') %}
{% set keyword = keyword_value|trim %}
{% set subject_key = keyword|lower %}
{% if keyword is not empty and subject_key not in subject_keys %}
{% set subjects = subjects|merge([keyword]) %}
{% set subject_keys = subject_keys|merge([subject_key]) %}
{% endif %}
{% endfor %}
{% endif %}
{% set personinimage = resource.personinimage|default('') %}
{% if personinimage|trim is not empty %}
{% for person_value in personinimage|split(',') %}
{% set person = person_value|trim %}
{% set subject_key = person|lower %}
{% if person is not empty and subject_key not in subject_keys %}
{% set subjects = subjects|merge([person]) %}
{% set subject_keys = subject_keys|merge([subject_key]) %}
{% endif %}
{% endfor %}
{% endif %}
{% set category_values = resource.category|default('') %}
{% if category_values|trim is not empty %}
{% for categorytemp in category_values|split(',') %}
{% for category in categorytemp|split('/')|slice(1) %}
{% set category_name = category|trim %}
{% set subject_key = category_name|lower %}
{% if category_name is not empty and subject_key not in subject_keys %}
{% set subjects = subjects|merge([category_name]) %}
{% set subject_keys = subject_keys|merge([subject_key]) %}
{% endif %}
{% endfor %}
{% endfor %}
{% endif %}
{% if subjects is not empty %}

{% for subject in subjects %}
    {{ subject|e }}
{% endfor %}

{% endif %}
